/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `update_product_status_after_borrow` AFTER INSERT ON `borrow_history` FOR EACH ROW BEGIN
    IF NEW.actual_return_date IS NULL THEN
        UPDATE products SET status = 'borrowed' WHERE id = NEW.product_id;
    END IF;
END */;;
